AssistantMessageToolRequest(name='create', tool_call_id='function-call-4c597687-c428-42ee-8c82-7dab693fefaf', arguments={'file_text': '/**
 * Simple React-like implementation for a standalone HTML page.
 */

const useState = (initialValue) => {
    let state = initialValue;
    const setState = (newValue) => {
        state = newValue;
        renderApp();
    };
    return [() => state, setState];
};

// Application state
const [getFormState, setFormState] = useState({
    values: {
        fullName: '',
        email: '',
        phone: ''
    },
    touched: {
        fullName: false,
        email: false,
        phone: false
    },
    errors: {
        fullName: '',
        email: '',
        phone: ''
    },
    isSubmitting: false,
    submitSuccess: false
});

const validate = (values) => {
    const errors = {};
    if (!values.fullName.trim()) {
        errors.fullName = 'Full name is required';
    }

    if (!values.email.trim()) {
        errors.email = 'Email address is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
        errors.email = 'Enter a valid email address (e.g., name@example.com)';
    }

    // Phone is optional, but if provided, we can check basic format if we wanted.
    // However, requirement only says optional and show helper text.
    // Let's stick to the requirements.

    return errors;
};

const handleBlur = (field) => {
    const currentState = getFormState();
    const newTouched = { ...currentState.touched, [field]: true };
    const newErrors = validate(currentState.values);
    setFormState({
        ...currentState,
        touched: newTouched,
        errors: newErrors
    });
};

const handleChange = (field, value) => {
    const currentState = getFormState();
    const newValues = { ...currentState.values, [field]: value };
    const newErrors = validate(newValues);
    setFormState({
        ...currentState,
        values: newValues,
        errors: newErrors
    });
};

const handleSubmit = (e) => {
    e.preventDefault();
    const currentState = getFormState();
    const errors = validate(currentState.values);

    if (Object.keys(errors).length > 0) {
        setFormState({
            ...currentState,
            touched: {
                fullName: true,
                email: true,
                phone: true
            },
            errors
        });

        // Focus first error
        const firstErrorField = Object.keys(errors)[0];
        document.getElementById(firstErrorField).focus();
        return;
    }

    setFormState({ ...currentState, isSubmitting: true });

    // Simulate API call
    setTimeout(() => {
        setFormState({
            ...getFormState(),
            isSubmitting: false,
            submitSuccess: true
        });
    }, 1000);
};

const FormField = ({ id, label, type, required, helperText, value, error, touched, autocomplete }) => {
    const showError = touched && error;
    const errorId = `${id}-error`;
    const helperId = `${id}-helper`;
    const describedBy = [];
    if (helperText) describedBy.push(helperId);
    if (showError) describedBy.push(errorId);

    return `
        <div class="form-field">
            <label for="${id}">
                ${label}
                ${required ? '<span class="required-asterisk" aria-hidden="true">*</span>' : ''}
            </label>
            <input 
                id="${id}" 
                name="${id}" 
                type="${type}" 
                value="${value}" 
                required="${required}"
                autocomplete="${autocomplete}"
                aria-required="${required}"
                aria-invalid="${showError ? 'true' : 'false'}"
                aria-describedby="${describedBy.join(' ')}"
                onblur="handleBlur('${id}')"
                oninput="handleChange('${id}', this.value)"
            >
            ${helperText ? `<p id="${helperId}" class="helper-text">${helperText}</p>` : ''}
            ${showError ? `<p id="${errorId}" class="error-message" role="alert">Error: ${error}</p>` : ''}
        </div>
    `;
};

const renderApp = () => {
    const state = getFormState();
    const root = document.getElementById('root');

    if (state.submitSuccess) {
        root.innerHTML = `
            <div class="support-page" role="status">
                <h1>Thank you!</h1>
                <p>Your message has been sent successfully. We'll get back to you soon.</p>
                <button onclick="location.reload()">Send another message</button>
            </div>
        `;
        return;
    }

    root.innerHTML = `
        <div class="support-page">
            <h1>Contact Support</h1>
            <form id="contact-form" novalidate onsubmit="handleSubmit(event)">
                ${FormField({
                    id: 'fullName',
                    label: 'Full Name',
                    type: 'text',
                    required: true,
                    autocomplete: 'name',
                    value: state.values.fullName,
                    error: state.errors.fullName,
                    touched: state.touched.fullName
                })}
                ${FormField({
                    id: 'email',
                    label: 'Email Address',
                    type: 'email',
                    required: true,
                    autocomplete: 'email',
                    value: state.values.email,
                    error: state.errors.email,
                    touched: state.touched.email
                })}
                ${FormField({
                    id: 'phone',
                    label: 'Phone Number (Optional)',
                    type: 'tel',
                    required: false,
                    autocomplete: 'tel',
                    helperText: 'Format: (123) 456-7890',
                    value: state.values.phone,
                    error: state.errors.phone,
                    touched: state.touched.phone
                })}
                <button type="submit" ${state.isSubmitting ? 'disabled' : ''}>
                    ${state.isSubmitting ? 'Sending...' : 'Send Message'}
                </button>
            </form>
        </div>
    `;
};

// Initial render
renderApp();
