                    label: 'Full Name',
                    type: 'text',
                    required: true,
                    autocomplete: 'name',
                    value: state.values.fullName,
                    error: state.errors.fullName,
                    touched: state.touched.fullName
                })}
                ${FormField({
                    id: 'email',
                    label: 'Email Address',
                    type: 'email',
                    required: true,
                    autocomplete: 'email',
                    value: state.values.email,
                    error: state.errors.email,
